import{_ as c,l as d,o as a,c as i,v as o,p as s,x as t,d as l,i as n,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"原子读改写","description":"","frontmatter":{"title":"原子读改写","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/atomic-rmw.md","filePath":"cs/atomic-rmw.md","lastUpdated":1789023840000}'),m={name:"cs/atomic-rmw.md"};function p(_,e,A,E,f,S){const r=d("Mermaid");return a(),i("div",null,[e[1]||(e[1]=o('<h1 id="原子读改写" tabindex="-1">原子读改写 <a class="header-anchor" href="#原子读改写" aria-label="Permalink to &quot;原子读改写&quot;">​</a></h1><div class="epigraph"><p>测试并置位、比较并交换、取并加，把「读—改—写」收成一条对总线可见的操作；没有它，锁字本身会竞争。</p><footer>—— 据 Dijkstra 之后的硬件实践；Love, Linux Kernel Development 整理</footer></div><p><a href="/cs/memory-barrier-os">上一课</a>钉住可见序，但锁字的「若为 0 则置 1」仍是两条访存，中间可被他核切开。<a href="/cs/race-critical">竞争</a> 的计数器例子正是这种切开。缺口是硬件 <strong>RMW 原子</strong>：<code>swap</code>、<code>cmpxchg</code>、<code>fetch_add</code>，在缓存一致性协议下对该地址表现为不可分。本课只钉对象，不写微架构延迟表。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>纯软件 Peterson 在 SC 上可互斥，在放宽模型加编译器下脆弱。内核与用户运行时默认用原子指令做锁与引用计数。缺口不是再讲 fence 的分类，而是：<strong>哪一类更新必须是 RMW</strong>——锁字、引用计数、无锁链表的头指针。失败的 CAS 还给出无锁算法的循环，后课再收。</p><p><span class="marginnote">RMW 通常对同一 cache 行上锁（MESI 的 M），他核要等行转手。这就是自旋锁缓存行乒乓的来源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>test_and_set</code>：读旧值并置 1，返回旧值，用来做最简自旋。<code>fetch_add</code>：引用计数。<code>cmpxchg</code>：期望值匹配才写成新值，否则返回当前。内核把它们包成 <code>atomic_t</code> 与 <code>atomic_long</code>，并规定是否自带屏障。本课不把每种 ISA 的 <code>lock</code> 前缀写完。</p>',8)),(a(),s(h,null,{default:t(()=>[n(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20RMW%5B%22%E5%8E%9F%E5%AD%90%E8%AF%BB%E6%94%B9%E5%86%99%22%5D%20--%3E%20TAS%5B%22%E6%B5%8B%E8%AF%95%E5%B9%B6%E7%BD%AE%E4%BD%8D%3A%20%E9%94%81%22%5D%0A%20%20RMW%20--%3E%20ADD%5B%22%E5%8F%96%E5%B9%B6%E5%8A%A0%3A%20%E8%AE%A1%E6%95%B0%22%5D%0A%20%20RMW%20--%3E%20CAS%5B%22CAS%3A%20%E6%9D%A1%E4%BB%B6%E6%9B%B4%E6%96%B0%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>单核关中断可以代替短 RMW，但挡不住多核；<a href="/cs/lock-irq">锁与关中断</a> 下一课把两者搭配。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>原子性相对的是该地址上的其它访存，不是全内存全序——全序仍要屏障。CAS 的「成功」只说明这一刻值匹配，不说明指针所指对象没被回收，那是 ABA，更后一课。引用计数用 fetch_add 避免丢失更新，仍要配对的屏障才能与对象内容同步。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 LL/SC 的伪失败与循环重试的全部细节，只承认有的 ISA 用 LL/SC 模拟 CAS。也不把业务逻辑写成「一条 CAS 事务」。用户态关中断不能代替 RMW：那是特权。</p><p>后课默认：锁字用原子 RMW 更新。内核里还要决定是否关本地 IRQ，下一课<a href="/cs/lock-irq">锁与关中断</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>RMW 让锁字与计数的读改写不可切。</li><li>CAS/TAS/fetch_add 是三类常用形态；跨核仍碰 cache 行。</li><li>与 IRQ 的搭配是下一课。</li><li>出处：Love, <em>LKD</em>；Silberschatz et al., <em>OSC</em>。</li></ul>',8))])}const D=c(m,[["render",p]]);export{u as __pageData,D as default};
